        recipients[0] = address(malicious);
        amounts[0] = 0.1 ether;

        // Second recipient: a dummy address to receive some ETH
        recipients[1] = address(0x123);
        amounts[1] = 0.1 ether;

        // Total amount we're sending: 0.2 ETH
        uint256 totalToSend = 0.2 ether;

